{"command":"cat <<'EOF' > /tmp/test_clap/src/main.rs
use std::process::{Command, Stdio};
use std::io::Read;
use std::os::unix::io::FromRawFd;

fn run_command(command_str: &str) -> (i32, String) {
    let mut fds = [0i32; 2];
    unsafe { libc::pipe(fds.as_mut_ptr()); }
    let mut reader = unsafe { std::fs::File::from_raw_fd(fds[0]) };
    let writer = unsafe { std::fs::File::from_raw_fd(fds[1]) };
    let writer2 = writer.try_clone().unwrap();

    let mut cmd = Command::new("sh");
    cmd.arg("-c").arg(command_str);
    cmd.stdout(Stdio::from(writer));
    cmd.stderr(Stdio::from(writer2));

    let mut child = cmd.spawn().unwrap();

    let reader_handle = std::thread::spawn(move || {
        let mut output_bytes = Vec::new();
        let _ = reader.read_to_end(&mut output_bytes);
        output_bytes
    });

    let status = child.wait().unwrap();
    let output_bytes = reader_handle.join().unwrap_or_default();
    let exit_code = status.code().unwrap_or(1);
    (exit_code, String::from_utf8_lossy(&output_bytes).to_string())
}

fn main() {
    let (code, out) = run_command("for i in $(seq 1 1000); do echo $i; done");
    println!("Exit code: {}, lines read: {}", code, out.lines().count());
}
EOF

