use std::time::{Duration, Instant};

fn parse_duration(s: &str) -> Result<Duration, String> {
    if s.is_empty() {
        return Err("expected number at 0".to_string());
    }

    let bytes = s.as_bytes();
    let mut pos = 0;
    let mut total_nanos: u128 = 0;

    while pos < bytes.len() {
        if !bytes[pos].is_ascii_digit() {
            if bytes[pos] == b'.' {
                return Err(format!("invalid character at {}", pos));
            } else {
                return Err(format!("expected number at {}", pos));
            }
        }

        let num_start = pos;
        while pos < bytes.len() && bytes[pos].is_ascii_digit() {
            pos += 1;
        }
        let num_str = &s[num_start..pos];
        let val: u128 = num_str.parse().map_err(|_| format!("invalid number at {}", num_start))?;

        let unit_start = pos;
        while pos < bytes.len() && (bytes[pos].is_ascii_alphabetic() || bytes[pos] == 0xC2 || bytes[pos] == 0xB5) {
            pos += 1;
        }
        let unit_str = &s[unit_start..pos];

        if unit_str.is_empty() {
            return Err(format!("unknown unit at {}-{}", unit_start, unit_start));
        }

        let nanos_per_unit: u128 = match unit_str {
            "ns" | "nanos" | "nanosecond" | "nanoseconds" => 1,
            "us" | "µs" | "micros" | "microsecond" | "microseconds" => 1_000,
            "ms" | "millis" | "millisecond" | "milliseconds" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60 * 1_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3600 * 1_000_000_000,
            "d" | "day" | "days" => 86400 * 1_000_000_000,
            "w" | "week" | "weeks" => 7 * 86400 * 1_000_000_000,
            "y" | "year" | "years" => 365 * 86400 * 1_000_000_000,
            _ => return Err(format!("unknown unit at {}-{}", unit_start, pos)),
        };

        total_nanos += val * nanos_per_unit;
    }

    let secs = (total_nanos / 1_000_000_000) as u64;
    let nanos = (total_nanos % 1_000_000_000) as u32;
    Ok(Duration::new(secs, nanos))
}

fn format_count(offset_str: &str, count_by_str: &str, iter: u64) -> String {
    let has_dot = offset_str.contains('.') || count_by_str.contains('.');
    if !has_dot {
        if let (Ok(offset_i), Ok(count_by_i)) = (offset_str.parse::<i64>(), count_by_str.parse::<i64>()) {
            return (offset_i + (iter as i64) * count_by_i).to_string();
        }
    }

    let offset_f: f64 = offset_str.parse().unwrap_or(0.0);
    let count_by_f: f64 = count_by_str.parse().unwrap_or(1.0);
    let val = offset_f + (iter as f64) * count_by_f;

    let dec_offset = offset_str.split('.').nth(1).map_or(0, |s| s.len());
    let dec_cb = count_by_str.split('.').nth(1).map_or(0, |s| s.len());
    let prec = dec_offset.max(dec_cb);

    if prec > 0 {
        format!("{:.1$}", val, prec)
    } else {
        format!("{}", val)
    }
}

fn run_command(command_str: &str, count: &str, actualcount: u64, item: Option<&str>) -> (i32, String) {
    let mut fds = [0i32; 2];
    unsafe { libc::pipe(fds.as_mut_ptr()); }
    let mut reader = unsafe { std::fs::File::from_raw_fd(fds[0]) };
    let writer = unsafe { std::fs::File::from_raw_fd(fds[1]) };
    let writer2 = match writer.try_clone() {
        Ok(w) => w,
        Err(_) => unsafe { std::fs::File::from_raw_fd(fds[1]) },
    };

    let mut cmd = ProcessCommand::new("sh");
    cmd.arg("-c").arg(command_str);
    cmd.env("COUNT", count);
    cmd.env("ACTUALCOUNT", actualcount.to_string());
    if let Some(it) = item {
        cmd.env("ITEM", it);
    }
    cmd.stdout(Stdio::from(writer));
    cmd.stderr(Stdio::from(writer2));

    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return (1, format!("failed to exec: {}\n", e)),
    };

    drop(cmd);

    let reader_handle = std::thread::spawn(move || {
        let mut output_bytes = Vec::new();
        let _ = reader.read_to_end(&mut output_bytes);
        output_bytes
    });

    let status = child.wait();
    let output_bytes = reader_handle.join().unwrap_or_default();
    let exit_code = match status {
        Ok(s) => s.code().unwrap_or(1),
        Err(_) => 1,
    };

    (exit_code, String::from_utf8_lossy(&output_bytes).to_string())
}

fn main() {
    let matches = Command::new("loop")
        .version("0.6.1")
        .author("Rich Jones <miserlou@gmail.com>")
        .about("UNIX's missing `loop` command")
        .arg(Arg::new("error_duration").short('D').long("error-duration").help("Exit with timeout error code on duration").action(ArgAction::SetTrue))
        .arg(Arg::new("only_last").short('l').long("only-last").help("Only print the output of the last execution of the command").action(ArgAction::SetTrue))
        .arg(Arg::new("stdin").short('i').long("stdin").help("Read from standard input").action(ArgAction::SetTrue))
        .arg(Arg::new("summary").long("summary").help("Provide a summary").action(ArgAction::SetTrue))
        .arg(Arg::new("until_changes").short('C').long("until-changes").help("Keep going until the output changes").action(ArgAction::SetTrue))
        .arg(Arg::new("until_fail").short('f').long("until-fail").help("Keep going until the command exit status is non-zero").action(ArgAction::SetTrue))
        .arg(Arg::new("until_same").short('S').long("until-same").help("Keep going until the output changes").action(ArgAction::SetTrue))
        .arg(Arg::new("until_success").short('s').long("until-success").help("Keep going until the command exit status is zero").action(ArgAction::SetTrue))
        .arg(Arg::new("count_by").short('b').long("count-by").help("Amount to increment the counter by").default_value("1"))
        .arg(Arg::new("every").short('e').long("every").help("How often to iterate. ex., 5s, 1h1m1s1ms1us").default_value("1us"))
        .arg(Arg::new("for").long("for").value_name("ffor").help("A comma-separated list of values, placed into $ITEM. ex., red,green,blue"))
        .arg(Arg::new("for_duration").short('d').long("for-duration").help("Keep going until the duration has elapsed (example 1m30s)"))
        .arg(Arg::new("num").short('n').long("num").help("Number of iterations to execute"))
        .arg(Arg::new("offset").short('o').long("offset").help("Amount to offset the initial counter by").default_value("0"))
        .arg(Arg::new("until_contains").short('c').long("until-contains").help("Keep going until the output contains this string"))
        .arg(Arg::new("until_error").short('r').long("until-error").help("Keep going until the command exit status is the value given"))
        .arg(Arg::new("until_match").short('m').long("until-match").help("Keep going until the output matches this regular expression"))
        .arg(Arg::new("until_time").short('t').long("until-time").help("Keep going until a future time, ex. \"2018-04-20 04:20:00\" (Times in UTC.)"))
        .arg(Arg::new("input").num_args(0..).trailing_var_arg(true).help("The command to be looped"))
        .get_matches();

    let inputs: Vec<String> = matches.get_many::<String>("input").unwrap_or_default().cloned().collect();
    if inputs.is_empty() {
        println!("No command supplied, exiting.");
        std::process::exit(0);
    }
    let command_str = inputs.join(" ");

    let error_duration = matches.get_flag("error_duration");
    let only_last = matches.get_flag("only_last");
    let stdin_flag = matches.get_flag("stdin");
    let summary_flag = matches.get_flag("summary");
    let until_changes = matches.get_flag("until_changes");
    let until_fail = matches.get_flag("until_fail");
    let until_same = matches.get_flag("until_same");
    let until_success = matches.get_flag("until_success");

    let count_by_str = matches.get_one::<String>("count_by").unwrap();
    let offset_str = matches.get_one::<String>("offset").unwrap();

    let every_str = matches.get_one::<String>("every").unwrap();
    let every_dur = match parse_duration(every_str) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: Invalid value for '--every <every>': {}", e);
            std::process::exit(1);
        }
    };

    let for_duration = if let Some(d_str) = matches.get_one::<String>("for_duration") {
        match parse_duration(d_str) {
            Ok(d) => Some(d),
            Err(e) => {
                eprintln!("error: Invalid value for '--for-duration <for_duration>': {}", e);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    let until_time = if let Some(t_str) = matches.get_one::<String>("until_time") {
        match NaiveDateTime::parse_from_str(t_str, "%Y-%m-%d %H:%M:%S") {
            Ok(ndt) => Some(ndt.and_utc()),
            Err(_) => {
                eprintln!("error: Invalid value for '--until-time <until_time>': timestamp format is invalid");
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    let until_match = if let Some(m_str) = matches.get_one::<String>("until_match") {
        match Regex::new(m_str) {
            Ok(re) => Some(re),
            Err(e) => {
                eprintln!("error: Invalid value for '--until-match <until_match>': {}", e);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    let until_contains = matches.get_one::<String>("until_contains");
    let until_error = matches.get_one::<String>("until_error");

    // Check num
    let num_arg = matches.get_one::<String>("num");

    // Collect items
    let mut items = Vec::new();
    if let Some(ffor) = matches.get_one::<String>("for") {
        for val in ffor.split(',') {
            items.push(val.to_string());
        }
    }

    if stdin_flag || !std::io::stdin().is_terminal() {
        let stdin = std::io::stdin();
        let lock = stdin.lock();
        for line in lock.lines() {
            if let Ok(line) = line {
                let trimmed = line.trim_end_matches(['\r', '\n']).to_string();
                items.push(trimmed);
            }
        }
    }

    let has_items = !items.is_empty();
    let max_iterations: Option<u64> = if let Some(n_str) = num_arg {
        match n_str.parse::<f64>() {
            Ok(n_f) => Some(n_f as u64),
            Err(_) => {
                eprintln!("error: Invalid value for '--num <num>': invalid float literal");
                std::process::exit(1);
            }
        }
    } else if has_items {
        Some(items.len() as u64)
    } else {
        None
    };

    let start_time = Instant::now();
    let mut iter: u64 = 0;
    let mut first_output: Option<String> = None;
    let mut last_output: String = String::new();

    let mut summary_total: usize = 0;
    let mut summary_successes: usize = 0;
    let mut summary_failures: Vec<i32> = Vec::new();
    let mut timeout_exit = false;

    loop {
        if let Some(max_i) = max_iterations {
            if iter >= max_i {
                break;
            }
        }

        if let Some(dur) = for_duration {
            if start_time.elapsed() >= dur {
                timeout_exit = true;
                break;
            }
        }

        if let Some(target_utc) = until_time {
            if Utc::now() >= target_utc {
                timeout_exit = true;
                break;
            }
        }

        let count_val = format_count(offset_str, count_by_str, iter);
        let item_val = if has_items {
            let idx = (iter as usize).min(items.len() - 1);
            Some(items[idx].as_str())
        } else {
            None
        };

        let (exit_code, out_str) = run_command(&command_str, &count_val, iter, item_val);

        summary_total += 1;
        if exit_code == 0 {
            summary_successes += 1;
        } else {
            summary_failures.push(exit_code);
        }

        last_output = out_str.clone();

        if !only_last {
            print!("{}", out_str);
            let _ = std::io::stdout().flush();
        }

        if until_fail && exit_code != 0 {
            break;
        }
        if until_success && exit_code == 0 {
            break;
        }
        if let Some(r_str) = until_error {
            if exit_code.to_string() == *r_str {
                break;
            }
        }
        if let Some(c_str) = until_contains {
            if out_str.contains(c_str) {
                break;
            }
        }
        if let Some(ref re) = until_match {
            if re.is_match(&out_str) {
                break;
            }
        }

        if until_changes {
            if iter == 0 {
                first_output = Some(out_str);
            } else if Some(&out_str) != first_output.as_ref() {
                break;
            }
        }

        if until_same {
            if iter == 0 {
                first_output = Some(out_str);
            } else if Some(&out_str) == first_output.as_ref() {
                break;
            }
        }

        iter += 1;
        std::thread::sleep(every_dur);
    }

    if only_last && summary_total > 0 {
        print!("{}", last_output);
        let _ = std::io::stdout().flush();
    }

    if summary_flag {
        if summary_failures.is_empty() {
            println!("Total runs:\t{}\nSuccesses:\t{}\nFailures:\t0", summary_total, summary_successes);
        } else {
            let fail_codes: Vec<String> = summary_failures.iter().map(|c| c.to_string()).collect();
            println!("Total runs:\t{}\nSuccesses:\t{}\nFailures:\t{} ({})", summary_total, summary_successes, summary_failures.len(), fail_codes.join(", "));
        }
    }

    if timeout_exit && error_duration {
        std::process::exit(124);
    }
}
EOF"}

