fn parse_duration(s: &str) -> Result<Duration, String> {
    if s.is_empty() {
        return Err("expected number at 0".to_string());
    }

    let bytes = s.as_bytes();
    let mut pos = 0;
    let mut total_nanos: u128 = 0;

    while pos < bytes.len() {
        if !bytes[pos].is_ascii_digit() {
            if bytes[pos] == b'.' {
                return Err(format!("invalid character at {}", pos));
            } else {
                return Err(format!("expected number at {}", pos));
            }
        }

        let num_start = pos;
        while pos < bytes.len() && bytes[pos].is_ascii_digit() {
            pos += 1;
        }
        let num_str = &s[num_start..pos];
        let val: u128 = num_str.parse().map_err(|_| format!("invalid number at {}", num_start))?;

        let unit_start = pos;
        while pos < bytes.len() && (bytes[pos].is_ascii_alphabetic() || bytes[pos] == 0xC2 || bytes[pos] == 0xB5) {
            pos += 1;
        }
        let unit_str = &s[unit_start..pos];

        if unit_str.is_empty() {
            return Err(format!("unknown unit at {}-{}", unit_start, unit_start));
        }

        let nanos_per_unit: u128 = match unit_str {
            "ns" | "nanos" | "nanosecond" | "nanoseconds" => 1,
            "us" | "µs" | "micros" | "microsecond" | "microseconds" => 1_000,
            "ms" | "millis" | "millisecond" | "milliseconds" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60 * 1_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3600 * 1_000_000_000,
            "d" | "day" | "days" => 86400 * 1_000_000_000,
            "w" | "week" | "weeks" => 7 * 86400 * 1_000_000_000,
            "y" | "year" | "years" => 365 * 86400 * 1_000_000_000,
            _ => return Err(format!("unknown unit at {}-{}", unit_start, pos)),
        };

        total_nanos += val * nanos_per_unit;
    }

    let secs = (total_nanos / 1_000_000_000) as u64;
    let nanos = (total_nanos % 1_000_000_000) as u32;
    Ok(Duration::new(secs, nanos))
}

fn format_count(offset_str: &str, count_by_str: &str, iter: u64) -> String {
    let has_dot = offset_str.contains('.') || count_by_str.contains('.');
    if !has_dot {
        if let (Ok(offset_i), Ok(count_by_i)) = (offset_str.parse::<i64>(), count_by_str.parse::<i64>()) {
            return (offset_i + (iter as i64) * count_by_i).to_string();
        }
    }

    let offset_f: f64 = offset_str.parse().unwrap_or(0.0);
    let count_by_f: f64 = count_by_str.parse().unwrap_or(1.0);
    let val = offset_f + (iter as f64) * count_by_f;

    let dec_offset = offset_str.split('.').nth(1).map_or(0, |s| s.len());
    let dec_cb = count_by_str.split('.').nth(1).map_or(0, |s| s.len());
    let prec = dec_offset.max(dec_cb);

    if prec > 0 {
        format!("{:.1$}", val, prec)
    } else {
        format!("{}", val)
    }
}

